<div class="page-heading"><p class="eyebrow">Organise</p><h1>Groups</h1><p class="muted">Group contacts for repeatable, deduplicated targeting. Membership never changes consent.</p></div>
<div class="two-col"><section class="panel"><h2>Your groups</h2><?php if(!$groups): ?><div class="empty-card"><h3>No groups yet</h3><p>Create a named group and select contacts for your next campaign.</p></div><?php else: ?><ul class="group-list"><?php foreach($groups as $g): ?><li><details><summary><span><strong><?= e($g['name']) ?></strong> <span class="muted">· <?= (int)$g['contact_count'] ?> contacts</span></span></summary>
<form method="post" action="<?= e(url('groups/update')) ?>" class="stack compact"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$g['id'] ?>"><label for="group-name-<?= (int)$g['id'] ?>">Group name</label><input id="group-name-<?= (int)$g['id'] ?>" name="name" value="<?= e($g['name']) ?>" required maxlength="120">
<fieldset><legend>Members</legend><div class="checkbox-list"><?php foreach($contacts as $c): ?><label class="check"><input type="checkbox" name="contact_ids[]" value="<?= (int)$c['id'] ?>" <?= in_array((int)$c['id'],array_map('intval',$g['member_ids']??[]),true)?'checked':'' ?>> <?= e($c['name']?:$c['phone_e164']) ?> <span class="muted small"><?= e($c['phone_e164']) ?></span></label><?php endforeach; ?></div></fieldset>
<div class="actions"><button class="button button-secondary" type="submit">Save group</button></div></form>
<form method="post" action="<?= e(url('groups/delete')) ?>" class="inline" data-confirm="Delete this group? Contacts are not deleted."><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$g['id'] ?>"><button class="link-button danger" type="submit">Delete group</button></form>
</details></li><?php endforeach; ?></ul><?php endif; ?></section>
<aside class="panel"><h2>Create a group</h2><form method="post" action="<?= e(url('groups/create')) ?>" class="stack"><?= csrf_field() ?><label for="group-name">Group name</label><input id="group-name" name="name" required maxlength="120" placeholder="e.g. Accra customers"><fieldset><legend>Add contacts <span class="muted">(optional)</span></legend><div class="checkbox-list scroll-list"><?php foreach($contacts as $c): ?><label class="check"><input type="checkbox" name="contact_ids[]" value="<?= (int)$c['id'] ?>"> <?= e($c['name']?:$c['phone_e164']) ?> <span class="muted small"><?= e($c['encrypted_phone']??$c['phone_e164']) ?></span></label><?php endforeach; ?><?php if(!$contacts): ?><p class="muted">No contacts yet.</p><?php endif; ?></div></fieldset><button class="button" type="submit">Create group</button></form></aside></div>
